/* Imported as CSS by T3 Code. The studio overrides these custom properties. */
@property --koi-size { syntax: "<number>"; inherits: false; initial-value: 1; }
@property --koi-sink { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --koi-exit-turn { syntax: "<angle>"; inherits: false; initial-value: 0deg; }

[data-workspace-area="conversation"] {
  position: relative;
  isolation: isolate;
  container-type: size;
  background: var(--koi-water-dark, #101010) !important;
}
:root:not(.dark) [data-workspace-area="conversation"] {
  background: var(--koi-water-light, #e5e5e5) !important;
}
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) > [data-assistant-citation-viewport] { position: relative; }

[data-workspace-area="conversation"]:not([data-side-chat-pane] *)::before,
[data-workspace-area="conversation"]:not([data-side-chat-pane] *)::after,
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) > [data-assistant-citation-viewport]::before,
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) > [data-assistant-citation-viewport]::after {
  position: absolute;
  inset: 0 auto auto 0;
  width: 112px;
  height: 46px;
  z-index: -1;
  pointer-events: none;
  opacity: .83;
  clip-path: path("M109 23 C109 15 103 11 94 11 C86 10 81 11 76 13 C69 9 63 5 53 4 C55 9 57 14 60 16 C49 17 41 21 31 21 C22 17 14 10 4 10 C7 17 11 23 13 24 C10 27 7 33 4 37 C16 36 21 29 31 26 C41 26 51 28 60 29 C58 34 55 39 53 42 C64 41 70 36 76 33 C81 35 86 36 94 35 C103 34 109 29 109 23 Z");
  --koi-ink: #181818;
  --koi-mark: #353535;
  --koi-light: #f2f2f2;
  --koi-fin: #717171;
  --koi-spot: #b9b9b9;
  --koi-duration: var(--koi-openai-time, 27s);
  --koi-track: t3-koi-openai;
  --koi-phase: -.24;
  background:
    radial-gradient(circle at 94% 38%, #181919 0 1.1px, transparent 1.9px),
    radial-gradient(circle at 94% 62%, #181919 0 1.1px, transparent 1.9px),
    radial-gradient(ellipse 9px 3px at 89% 46%, #fff9, transparent),
    radial-gradient(ellipse 15px 11px at 76% 45%, var(--koi-mark) 60%, transparent 86%),
    radial-gradient(ellipse 11px 6px at 66% 65%, var(--koi-spot) 50%, transparent 90%),
    radial-gradient(ellipse 13px 9px at 56% 43%, var(--koi-ink) 60%, transparent 88%),
    radial-gradient(ellipse 10px 8px at 40% 55%, var(--koi-mark) 60%, transparent 91%),
    repeating-linear-gradient(145deg, transparent 0 3px, #28251c17 4px, transparent 5px),
    linear-gradient(0deg, var(--koi-fin), var(--koi-light) 40% 59%, var(--koi-fin));
  transform-origin: center;
  transform: translate(calc(var(--koi-still-x, 25) * 1cqw - 56px), calc(var(--koi-still-y, 76) * 1cqh - 23px + var(--koi-sink, 0px))) rotate(var(--koi-still-angle, -15deg)) scale(var(--koi-size, 1)) rotate(var(--koi-exit-turn, 0deg));
  animation: var(--koi-track) var(--koi-duration) linear calc(var(--koi-duration) * var(--koi-phase)) infinite;
}
[data-workspace-area="conversation"]:not([data-side-chat-pane] *)::before { content: ""; }

[data-workspace-area="conversation"]:not([data-side-chat-pane] *):has([data-subagent-group]:not([data-side-chat-pane] *) > [aria-expanded] > [aria-hidden="true"] > span:nth-child(1))::after,
