  animation-play-state: paused;
  transition: opacity 850ms ease, --koi-size 850ms ease, --koi-exit-turn 850ms ease, --koi-sink 850ms ease;
  --koi-phase: -0.6;
  --koi-still-x: 75;
  --koi-still-y: 78;
  --koi-still-angle: 18deg;
}
